targets.query:
from(bucket: "pihole")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "queries")
  |> filter(fn: (r) => r["_field"] == "total")
  |> map(fn: (r) => ({
    r with
    _time: time(v: int(v: (int(v: r._time) + 5000000000)) / 10000000000 * 10000000000)
  }))
  |> derivative(unit: 10s, nonNegative: true)
  |> aggregateWindow(every: ${Precision}, fn: sum, createEmpty: false)
  |> map(fn: (r) => ({
    r with
    _value: if exists r._value then int(v: r._value) else 0
  }))
  |> yield(name: "last")

